												<Button :variant="'outline'" :ref_for="true" theme="gray" size="sm" label="Go to Therapy Session"
													:disabled="!row.is_physio_appointment && !row.is_physio_pract" @click="open_therapy(row.name)">
													<div class="flex items-center truncate">
