											</div>
										</div>
										<div v-if="column.key === 'status'">
											<div class="px-1 py-1 text-center place-content-center">
												<Button :variant="'outline'" size="sm" :label="row.status" :class="row.statusClass"
													@click="statusopened(row)">
													{{ row.status }}
												</Button>
											</div>
											<div class="px-1 py-1 text-xss text-center !text-green-500 place-content-center"
												v-if="row.token_su_name">
												{{ row.token_su_name }}
											</div>
										</div>
										<div v-if="column.key === 'service'">
											<div class="px-1 py-1 text-sm">
												{{ row.app_service_unit_name }}
