			size: 'xl',
			icon: {
				name: 'alert-triangle',
				appearance: 'warning',
			},
			actions: [
				{
					label: 'Confirm',
					variant: 'solid',
					onClick: () => {
						return go_to_desk_page();
					},
				},
				{
					label: 'Cancel',
					onClick: () => {
						return confirm_to_desk_dialog = false;
					},
				},
			],
		}" v-model="confirm_to_desk_dialog"/>
	</div>

	<Dialog v-model="select_encounter_type_dialog" :options="{
		size: 'xl',
	}">
		<template #body-title>
			<h3 class="font-bold">Select Encounter Type</h3>
		</template>
		<template #body-content>
			<div class="mb-4">
				<div class="grid grid-cols-2 gap-2 py-2">
					<div class="py-1 w-full">
						<FormControl type="text" label="Patient" v-model="enc_patient" size="sm" variant="subtle"
							:disabled="true" />
					</div>
					<div class="py-1 w-full">
						<FormControl type="text" label="Patient ID" v-model="enc_patient_id" size="sm"
							variant="subtle" :disabled="true" />
					</div>
					<div class="py-1 w-full">
						<FormControl type="text" label="Patient Appointment" v-model="enc_pa" size="sm"
							variant="subtle" :disabled="true" />
					</div>
					<div class="py-1 w-full">
						<FormControl type="text" label="Practitioner" v-model="enc_pract" size="sm"
							variant="subtle" :disabled="true" />
					</div>
				</div>
				<div class="grid grid-cols-2 gap-2">
					<div class="py-1 w-full">
						<FormControl type="select" :options="enc_type_options" label="Encounter Type"
							v-model="enc_type" size="sm" variant="subtle" :required="true" />
						<ErrorMessage v-if="errors.enc_type"
							:message="errors.enc_type" />
					</div>
				</div>
			</div>
			<div>
				<ErrorMessage v-if="errors.enc_error" :message="errors.enc_error" />
			</div>
		</template>
		<template #actions>
			<Button variant="solid" @click="create_encounter()">Create Encounter</Button>
		</template>
	</Dialog>
</template>

<style scoped>
::v-deep(.text-blue-600) {
	color: #2563eb !important;
}

::v-deep(.text-purple-400) {
	color: #964dc0 !important;
}
</style>

<script setup>
import { ref, watch, computed, reactive, onMounted, inject } from 'vue';
import {
	createResource,
	DatePicker,
	Button,
	Dialog,
	FormControl,
	Tabs,
	Tooltip,
	ListView,
	ListFooter,
	ListHeader,
	ListHeaderItem,
	ListRows,
	ListRow,
	ListRowItem,
	Avatar,
	ErrorMessage
} from 'frappe-ui';

const activeTab = ref(0);
const columns = ref([
	{ label: "Patient", key: "patient_name", icon: "user", width: "250px", align: "left" },
	{ label: "Patient Details", key: "patient_details", icon: "archive", width: "220px", align: "left" },
	{ label: "Appointment Details", key: "appointment_details", icon: "clipboard", width: "230px", align: "left" },
	{ label: "Time", key: "appointment_time_", icon: "clock", width: "150px", align: "center" },
	{ label: "Token No", key: "patient_token_number", icon: "log-in", width: "110px", align: "center" },
	{ label: "Room", key: "service", icon: "archive", width: "260px", align: "center" },
	{ label: "Status", key: "status", icon: "check-circle", width: "180px", align: "center" },
	{ label: "Actions", key: "actions", icon: "chevrons-right", width: "240px", align: "center" },
]);

const succes_or_error_dialog = ref(false);
const pageLengthCount = defineModel()
let dialog_message = ref("");
let dialog_title = ref("");
let search = ref(null);
let searchOptions = ref([]);
let mobile_search = ref(null);
let token_search = ref("");
let date_search = ref("");
let patient_search = ref("");
let patient_search_options = ref([]);
let appointment_type = ref("");
let appointment_options = ref([]);
let sort_by = ref("");
let confirm_to_desk_dialog = ref(false);
let page_limit = ref(20);
let row_data = ref([]);
let select_encounter_type_dialog = ref(false);
let enc_patient = ref("");
let enc_patient_id = ref("");
let enc_type = ref("");
let enc_pa = ref("");
let enc_pract = ref("");
let enc_type_options = ref([]);
let errors = ref({});

const emit = defineEmits([
	'loadMore',
	'updatePageCount',
	'columnWidthUpdated',
	'applyFilter',
	'applyLikeFilter',
	'likeDoc',
])

let tabs = computed(() => [
	{ label: `In Queue (0)`, "name": "Open", "appointments": [] },
	{ label: `Attending (0)`, "name": "Checked Out", "appointments": [] },
	{ label: `Consulted (0)`, "name": "Consulted", "appointments": [] },
	{ label: `All (0)`, "name": "All", "appointments": [] },
]);

// realtime encounter submition status change
const socket = inject("$socket");
if (socket) {
	onMounted(() => {
		socket.on("update_appointment_status", (data) => {
			get_appointments.reload();
		});
	});
}

let logo = ref("");
let get_logo = createResource({
	url: "/api/method/marley_frontend.api.get_logo_image",
	method: "GET",
	makeParams() {
		return {};
	},
	onSuccess(response) {
		if (response) {
			logo.value = response;
		}
		else {
			logo.value = "https://raw.githubusercontent.com/frappe/healthcare/develop/healthcare/public/images/healthcare.svg";
		}
	},
})
get_logo.fetch()

let get_appointments = createResource({
	url: '/api/method/marley_frontend.practitioner_screen.get_appointments',
	method: 'GET',
	makeParams() {
		return {
			token_search: token_search?.value || null,
			patient_search: patient_search.value?.value || null,
			mobile_search: mobile_search?.value || null,
			appointment_search: search.value?.value || null,
			appointment_type: appointment_type.value?.value || null,
			sort_by: sort_by?.value || null,
			limit: page_limit?.value || null,
			date: date_search?.value || null
		};
	},
	onSuccess(response) {
		searchOptions.value = response.appointment_options;
		enc_type_options.value = response.enc_type_options;
		tabs = computed(() => response.formatted_data);
	},
	onError(error) {
		dialog_title = "Fetching Appointments Failed";
		dialog_message = error.messages?.[0] || error;
		succes_or_error_dialog.value = true;
	}
});

get_appointments.fetch();

watch(search, () => {
	get_appointments.reload();
});

watch(patient_search, () => {
	get_appointments.reload();
});

watch(token_search, () => {
	get_appointments.reload();
});

watch(date_search, () => {
	get_appointments.reload();
});

watch(mobile_search, () => {
	get_appointments.reload();
});

watch(appointment_type, () => {
	get_appointments.reload();
});

watch(sort_by, () => {
	get_appointments.reload();
});

watch(pageLengthCount, (val, old_value) => {
	if (val === old_value) return
	page_limit.value = val;
	get_appointments.reload();
});

function navigateToDoctype(row) {
	row_data.value = row;
	if (row.encounter) {
		window.location.href = "/app/patient-encounter/" + row.encounter;
	} else {
		enc_patient.value = row.patient_name;
		enc_patient_id.value = row.patient;
		enc_pa.value = row.name;
		enc_type = "";
		enc_pract.value = row.practitioner_name;
		select_encounter_type_dialog.value = true;
	}
}

let create_encounter = async () => {
	let make_encounter = createResource({
		url: '/api/method/marley_frontend.practitioner_screen.make_encounter',
		method: 'POST',
		makeParams() {
			return {
				appointment: row_data.value?.name || null,
				token: row_data.value?.token || null,
				current_unit: row_data.value?.token_su || null,
				enc_type: enc_type || null
			};
		},
		onSuccess(response) {
			if (response) {
				if (response.success) {
					window.location.href = "/app/patient-encounter/" + response.encounter;
					get_appointments.reload();
				} else {
					dialog_title = "Encounter Creation Failed";
					dialog_message = response.message;
					succes_or_error_dialog.value = true;
				}
			}
		},
		onError(error) {
			dialog_title = "Encounter Creation Failed";
			dialog_message = error.messages?.[0] || error;
			succes_or_error_dialog.value = true;
		},
	});

	if (!enc_type) {
		errors.value.enc_type = "This field is required";
	} else {
		errors.value.enc_type = "";
	}
	if (!enc_type) {
		return
	} else {
		select_encounter_type_dialog.value = false;
		await make_encounter.submit();
	}
}

function open_patient_desk(row) {
	window.location.href = "/app/patient/" + row.patient;
}

// Fetch initial data for departments, practitioners, and appointment types
const { fetch } = createResource({
	url: '/api/method/marley_frontend.practitioner_screen.get_search_options',
	method: 'GET',
	makeParams() {
		return {
			status: "Active"
		};
	},
	onSuccess(response) {
		appointment_options.value = response.appointment_type_list;
		patient_search_options.value = response.patient_list;
	},
	onError(error) {
		dialog_title = "Fetching Search Options Failed";
		dialog_message = error.messages?.[0] || error;
		succes_or_error_dialog.value = true;
	},
});
fetch();

function handleCall(token, service_unit, appointmentId) {
	check_if_called(appointmentId)
		.then(() => {
			mark_as_called(appointmentId);
		})
		.catch(error => {
			dialog_title = "Calling Patient Failed";
			dialog_message = error.messages?.[0] || error;
			succes_or_error_dialog.value = true;
		});

	let token_call = createResource({
		url: '/api/method/marley_frontend.api.trigger_call',
		method: 'GET',
		makeParams() {
			return {
				token: token,
				service_unit: service_unit
			};
		},
		onError(error) {
			dialog_title = "Calling Failed";
			dialog_message = error.messages?.[0] || error;
			succes_or_error_dialog.value = true;
		},
	});

	token_call.submit();
}

function check_if_called(appointmentId) {
	return new Promise((resolve, reject) => {
		let check_called = createResource({
			url: '/api/method/marley_frontend.practitioner_screen.check_if_called',
			method: 'GET',
			makeParams() {
				return { last_called_appointment: appointmentId }; // Send current call
			},
			onSuccess(response) {
				if (response.appointment_ids && response.appointment_ids.length > 0) {
					get_appointments.reload();
				}
				resolve(response); // Resolve the Promise when the request is successful
			},
			onError(error) {
				reject(error); // Reject the Promise if there's an error
			}
		});
		check_called.fetch();
	});
}

function mark_as_called(appointmentId) {
	let mark_called = createResource({
		url: '/api/method/marley_frontend.practitioner_screen.mark_as_called',
		method: 'POST',
		makeParams() {
			return { appointment_id: appointmentId };
		},
		onSuccess(response) {
			if (response.error) {
				dialog_title = "Mark Calling Failed";
				dialog_message = response.error;
				succes_or_error_dialog.value = true;
			} else {
				get_appointments.reload();
			}
		},
		onError(error) {
			dialog_title = "Mark Calling Failed";
			dialog_message = error.messages?.[0] || error;
			succes_or_error_dialog.value = true;
		}
	})
	mark_called.submit();
}

function open_therapy(appointment) {
	let therapy_session = createResource({
		url: '/api/method/marley_frontend.practitioner_screen.route_to_therapy',
		method: 'POST',
		makeParams() {
			return {
				appointment: appointment
			};
		},
		onSuccess(response) {
			if (response) {
				window.location.href = "/app/therapy-session/" + response.session;
			}
		},
		onError(error) {
			dialog_title = "Therapy Session Creation Failed";
			dialog_message = error.messages?.[0] || error;
			succes_or_error_dialog.value = true;
		},
	});
	therapy_session.submit();
}

function confirm_to_desk() {
	confirm_to_desk_dialog.value = true;
}

function go_to_desk_page(){
	window.location.href = "/app";
}

function clear_filters() {
	search.value = "";
	mobile_search.value = "";
	token_search.value = "";
	sort_by.value = "";
	patient_search.value = "";
	appointment_type.value = "";
}
</script>
